"""Format field labels and values.

    Parameters
    ----------
    field_data : |list| of |tuple|
       2-tuples of field labels and values.

    include_empty : |bool|, optional
        Whether fields whose values are |None| or an empty |str| should
        be included in the formatted fields.

    Returns
    -------
    str
        Formatted field labels and values.

    Examples
    --------
    >>> field_data = [('Name', 'Jane'), ('Age', 30), ('DOB', None)]
    >>> format_fields(field_data, include_empty=True)
    Name: Jane
    Age:  30
    DOB:  None

    >>> field_data = [('Name', 'Jane'), ('Age', 30), ('DOB', None)]
    >>> format_fields(field_data, include_empty=False)
    Name: Jane
    Age:  30

    """
def format_fields(field_data: Any, include_empty: Any = True) -> object {
    max_label = 0;
    for (label, value) in field_data {
        label_length = len(label);
        if (label_length > max_label) {
            max_label = label_length;
        }
    }
    fields = [];
    for (label, value) in field_data {
        empty = str(value).strip() in ['', 'None'];
        if (not empty or include_empty) {
            label_length = len(label.strip());
            extra_spaces = ' ' * (max_label - label_length);
            label_sep = ':' + extra_spaces + ' ';
            joined_field = label_sep.join([label, str(value)]);
            fields.append(joined_field);
        }
    }
    return '\n'.join(fields);
}

"""
    Return a new parameters dict with the magnet parameters in the form
    '<prefix>_<magnet>_<segment>', with the values from 'magnet_parameters'
    and other parameters from 'params'.

    The length of the array 'magnet_parameters' must be equal to the sum of
    the number of segments in both cylinders.

    The first n_II elements refer to the inner magnet,
    and the remaining elements to the outer magnet.
    """
def expand_parameters_from_remanence_array(
    magnet_parameters: Any, params: Any, prefix: Any
) -> object {
    params_expanded = params.copy();
    n_II = params["n_II"];
    for i in range(0, n_II) {
        params_expanded[("%s_II_%d" % (prefix, (i + 1)))] = magnet_parameters[i];
    }
    n_IV = params["n_IV"];
    for j in range(0, n_IV) {
        k = j + n_II;
        params_expanded[("%s_IV_%d" % (prefix, (j + 1)))] = magnet_parameters[k];
    }
    return params_expanded;
}

