def modpos(pos: Any, L: Any, move: Any) -> object {
    pos += move;
    return pos;
}

"""
	find letter in word , return first occurence
	"""
def find(word: Any, letter: Any) -> object {
    index = 0;
    while (index < len(word)) {
        if (word[index] == letter) {
            return index;
        }
        index = index + 1;
    }
    return -1;
}

"""
    Returns the length (number of letters) in the current hand.

    hand: dictionary (string-> int)
    returns: integer
    """
def calculate_handlen(hand: Any) -> object {
    hand_len = 0;
    for key in hand.keys() {
        hand_len += hand[key];
    }
    return hand_len;
}

"""
    It returns given vocal with grave or acute accent
    """
def getAccentedVocal(vocal: Any, acc_type: Any = "g") -> object {
    vocals = {
        'a': {'g': '\xe0', 'a': '\xe1'},
        'e': {'g': '\xe8', 'a': '\xe9'},
        'i': {'g': '\xec', 'a': '\xed'},
        'o': {'g': '\xf2', 'a': '\xf3'},
        '': {'g': '\xf9', 'a': '\xfa'}
    };
    return vocals[vocal][acc_type];
}
